 /// `""` for another host (or a class without a lab: byteplus, alibaba).
 pub fn lab_of_host(host: &str) -> &'static str {
     let h = host.to_lowercase();
     let is = |d: &str| h == d || h.ends_with(&format!(".{d}"));
     if is("openai.com") || is("chatgpt.com") {
         "openai"
